head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.SEL_TP_ALL = "3";     // 부모 선택 구분 — 전체 (원본 keyGubun == "3" 이면 발행회사코드를 비워 전 종목 조회)
scwin.isurCd = "";          // 조회할 발행기관코드 (원본 keyIsurCd)

// 원본 : /etn/ULDSTF08037.gfm (ETN 관리종목지정 해제대상 종목선택 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF08033_new)가 넘긴 발행기관의 해제 대상 종목(공시 완료된 지정건 중 아직 해제되지 않은 종목)을 왼쪽에 조회한다.
 *    부모 선택 구분이 전체(3)면 발행기관을 비워 전 종목을 조회한다.
 *  - [▶]·왼쪽 더블클릭은 고른 종목을 오른쪽에 더하고(같은 종목은 한 번만, 종목명 순), [▶▶]는 왼쪽 전부로 오른쪽을 바꾼다.
 *    [◀]·오른쪽 더블클릭은 고른 행을, [◀◀]는 오른쪽 전부를 뺀다.
 *  - [확인]은 오른쪽 목록을 { list : [...] } 로 돌려주고 닫는다. 닫기는 창 X(isCloseButtonClick).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08037/ULDSTF08037.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08037.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 부모가 넘긴 발행기관·선택 구분을 받아(전체면 발행기관을 비움) 해제대상 종목을 조회한다. 부모가 이미 고른 목록(list)을 넘기면 오른쪽에 미리 채운다.
 * (원본 gform onload — fn_GetPar(arrPar, dts_selectleadcom) → keyIsurCd·keyGubun → fn_set_code, 공통 계약서 §3.3 — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 부모 data { isurCd, selTp } (원본 arrPar[0] 발행기관코드 · arrPar[1] 선택 구분)
    const param = $c.data.getParameter() ?? {};
    scwin.isurCd = (param.selTp === scwin.SEL_TP_ALL) ? "" : (param.isurCd ?? "");

    // 2) 부모가 이미 고른 종목 — 원본 fn_GetParIsu 의 CopyDataSet(dts_Isu_Mst_Temp, param_dts). 계약서에 없는 선택 키라 없으면 빈 목록 (§10 #3)
    if (Array.isArray(param.list) && param.list.length > 0) {
        dlt_selList.setJSON(param.list);
    }

    // 3) 해제대상 종목 조회 (원본 fn_set_code)
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.grd_leadcom_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제대상 목록(왼쪽) 행 더블클릭 — 그 종목을 고른 목록에 더한다. (원본 grd_leadcom OnDblClick → fn_add)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_leadcom_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.add(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.grd_leadcom_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.grd_selectleadcom_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 목록(오른쪽) 행 더블클릭 — 그 행을 뺀다. (원본 grd_selectleadcom OnDblClick → fn_del)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_selectleadcom_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.del(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.grd_selectleadcom_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.img_rightarr_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [▶] 클릭 — 왼쪽에서 포커스된 종목을 고른 목록에 더한다. (원본 img_rightarr onclick → fn_add)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_rightarr_onclick = function (e) {
    try {
        scwin.add(grd_leadcom.getFocusedRowIndex());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.img_rightarr_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_rightarr_all_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [▶▶] 클릭 — 왼쪽 전부로 고른 목록을 바꾼다. (원본 img_rightarr_all onclick → fn_add_all)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_rightarr_all_onclick = function (e) {
    try {
        scwin.addAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.img_rightarr_all_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_leftarr_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [◀] 클릭 — 고른 목록에서 포커스된 행을 뺀다. (원본 img_leftarr onclick → fn_del)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_leftarr_onclick = function (e) {
    try {
        scwin.del(grd_selectleadcom.getFocusedRowIndex());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.img_leftarr_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_leftarr_all_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [◀◀] 클릭 — 고른 목록을 모두 비운다. (원본 img_leftarr_all onclick → fn_del_all)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_leftarr_all_onclick = function (e) {
    try {
        scwin.delAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08037.img_leftarr_all_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_confirm_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description [확인] 클릭 (원본 btn_confirm onclick → fn_confirm)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_confirm_onclick = async function (e) {
    try {
        await scwin.confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08037.btn_confirm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제대상 종목 조회 — 발행기관코드를 보낸다(빈 값이면 전 종목). (원본 fn_set_code — DIV_ETN_IDX_ADMISU_ISU_RELEAS, 공용 명세 §2 — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-list-releas-isu",
        target : "dlt_listReleasIsu=body",
        gridview : "grd_leadcom",
        isProcessMsg : false
    };

    // 공용 명세 §2 requestData { isurCd }
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError·OnFail → alert_error)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.add
 * @author Inswave
 * @date 2026. 10. 30
 * @description 왼쪽 행 하나를 고른 목록에 더한다 — 같은 종목코드가 이미 있으면 그대로 두고, 더한 뒤 종목명 오름차순으로 정렬한다.
 * (원본 fn_add + fn_add_dts_select — 원본은 응답 19열을 열마다 옮겼다, §6.1)
 * @param {Number} rowIndex 왼쪽 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.add = function (rowIndex) {
    if (rowIndex < 0 || rowIndex >= dlt_listReleasIsu.getRowCount()) return;

    const isuCd = dlt_listReleasIsu.getCellData(rowIndex, "isuCd");
    for (let i = 0; i < dlt_selList.getRowCount(); i++) {
        if (dlt_selList.getCellData(i, "isuCd") === isuCd) return;
    }

    // 원본 SortExpr="+ISU_NM" — 종목명 오름차순
    const rows = dlt_selList.getAllJSON();
    rows.push(dlt_listReleasIsu.getRowJSON(rowIndex));
    rows.sort((a, b) => String(a.isuNm ?? "").localeCompare(String(b.isuNm ?? "")));
    dlt_selList.setJSON(rows);
};

/**
 * @method
 * @name scwin.addAll
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 목록을 왼쪽 전부로 바꾸고 첫 행에 포커스한다(정렬하지 않음 — 원본과 같음). (원본 fn_add_all — §6.1)
 * @returns
 * @hidden N
 */
scwin.addAll = function () {
    dlt_selList.setJSON(dlt_listReleasIsu.getAllJSON());
    if (dlt_selList.getRowCount() > 0) {
        grd_selectleadcom.setFocusedCell(0, "isuNm");
    }
};

/**
 * @method
 * @name scwin.del
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 목록에서 행 하나를 뺀다. (원본 fn_del — §6.1)
 * @param {Number} rowIndex 고른 목록 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.del = function (rowIndex) {
    if (rowIndex < 0 || rowIndex >= dlt_selList.getRowCount()) return;
    dlt_selList.removeRow(rowIndex);
};

/**
 * @method
 * @name scwin.delAll
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 목록을 모두 비운다. (원본 fn_del_all — §6.1)
 * @returns
 * @hidden N
 */
scwin.delAll = function () {
    dlt_selList.removeAll();
};

/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 목록을 { list : [...] } 로 돌려주고 닫는다. 빈 목록이면 부모가 취소로 본다(공통 계약서 §3.3). (원본 fn_confirm — fn_SetPar(dts_selectleadcom) + CloseFrame, §6.2)
 * @returns
 * @hidden N
 */
scwin.confirm = async function () {
    await $c.win.closePopup({ list : dlt_selList.getAllJSON() });
};
